function ChaoticRecallUtils.GetIsPassById(groupId,nodeId)
    local dojo = ChaoticRecallUtils.GetChaoticRecallMgr():GetHomeDojo()
    if not isNull(dojo) then
        local groups = dojo:GetGroups()
        local nodeVo = ChaoticRecallUtils.GetChaoticRecallNodeVo(nodeId)
        for i, v in pairs(groups) do
            if checkNumber(v.groupId) == groupId then
                local nodes = v.nodes
                local node = nodes[nodeVo.place]
                if not isNull(node) then
                    return node.passed == 1
                end
            end
        end
    end
    return false
end

function ChaoticRecallUtils.GetVosByGroupId(groupId)
    local allData = CfUtils.GetCf(AutoIds.IdSetting6111,"ChaoticRecallStarRewardVo",true)
    local allVos = {}
    for i, v in pairs(allData) do
        if v.groupId == checkNumber(groupId) then
            table.insert(allVos,v)
        end
    end
    return allVos
end

function ChaoticRecallUtils.IsGroupHaveRedPoint(groupId,index)
    local progressReward = ChaoticRecallUtils.IsHaveProgressReward(groupId, index)
    if progressReward then
        return true
    end
    
    local rankReward = ChaoticRecallUtils.IsHaveRankReward(groupId, index)
    if rankReward then
        return true
    end
    
    local isHaveStarPoint = ChaoticRecallUtils.IsHaveStarRedPoint(groupId,index)
    if isHaveStarPoint then
        return true
    end
    
    return false
end

function ChaoticRecallUtils.IsHaveRankReward(groupId, index)
    local vo = ChaoticRecallUtils.GetChaoticRecallTagVo(groupId)
    if vo.groupType == 1 then
        local dojo = ChaoticRecallUtils.GetChaoticRecallMgr():GetHomeDojo()
        local isGet = dojo:IsGetRankReward(index)
        if not isGet then
            return true
        end
    end
    return false
end

function ChaoticRecallUtils.IsHaveStarRedPoint(groupId, index)
    local allVos = ChaoticRecallUtils.GetVosByGroupId(checkNumber(groupId))
    local dojo = ChaoticRecallUtils.GetChaoticRecallMgr():GetHomeDojo()
    local curStarNum = dojo:GetAllPassStar(index)
    local starReceived = dojo:GetStarReceiveData(index)
    for i, v in pairs(allVos) do
        local isGet = ChaoticRecallUtils.IsGet(v.starLevel,starReceived)
        if not isGet and curStarNum >= checkNumber(v.starLevel) then
            return true
        end
    end
    return false
end

function ChaoticRecallUtils.IsHaveProgressReward(groupId, index)
    local vo = ChaoticRecallUtils.GetChaoticRecallTagVo(groupId)
    local dojo = ChaoticRecallUtils.GetChaoticRecallMgr():GetHomeDojo()
    local nodeData = dojo:GetNodeData(index)
    if table.count(vo.rewards) > 0 then
        local total = 0
        local progress = 0
        for i, v in pairs(nodeData) do
            for j, node in ipairs(v) do
                total = total + 1
                if node.passed == 1 then
                    progress = progress + 1
                end
            end
        end
        local isGet = dojo:IsGetProgressReward(index)
        if progress == total and not isGet then
            return true
        end
    end
    return false
end

function ChaoticRecallUtils.IsGet(starLevel,starReceived)
    for i, v in pairs(starReceived) do
        if v == checkNumber(starLevel) then
            return true
        end
    end
    return false
end

function ChaoticRecallUtils.IsLimitCard(questId,cardId,teamIndex)
    local teamInfo = ChaoticRecallUtils.GetChaoticRecallMgr():GetTeamInfoByQuestId(questId)
    if not teamInfo then
        return false
    end

    local levelVo =  ChaoticRecallUtils.GetChaoticRecallLevelVo(questId)
    if levelVo then
        local count = levelVo.nodeTeamCount
        for i, j in pairs(teamInfo) do
            if checkNumber(i) ~= teamIndex and i <= count then
                local cardsInfo = j.cardsInfo
                if not isNull(cardsInfo) and table.count(cardsInfo) > 0 then
                    for k, v in pairs(cardsInfo) do
                        if v.refId == checkNumber(cardId) then
                            return true
                        end
                    end
                end
            end
        end
    end

    return false
end

function ChaoticRecallUtils.IsLimitCat(questId,catId,teamIndex)
    local teamInfo = ChaoticRecallUtils.GetChaoticRecallMgr():GetTeamInfoByQuestId(questId)
    if not teamInfo then
        return false
    end

    local levelVo =  ChaoticRecallUtils.GetChaoticRecallLevelVo(questId)
    if levelVo then
        local count = levelVo.nodeTeamCount
        for i, j in pairs(teamInfo) do
            if checkNumber(i) ~= teamIndex and i <= count then
                local catsInfo = j.catsInfo
                if not isNull(catsInfo) and table.count(catsInfo) > 0 then
                    for k, v in pairs(catsInfo) do
                        if v.playerCatId == checkNumber(catId) then
                            return true
                        end
                    end
                end
            end
        end
    end

    return false
end

